/**
 * B-1575: a server key generated by this process while older keys.json files
 * exist blocks the vendor-key boot and daily sweeps (those files were sealed
 * under another key). A key read from an existing file never blocks them.
 */
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { after, beforeEach, test } from 'node:test';

// B-1544: must stay the first app-side import (HOME, DATABASE_PATH, harness roots).
import { assertInsideSandbox, removeSandbox, sandboxHome } from '../tests/helpers/hermetic-sandbox.js';

delete process.env.NASSAJ_PROVIDER_SECRETS_KEY;
delete process.env.NASSAJ_PROVIDER_SECRETS_KEY_FD;

const store = await import('@/services/isolation/provider-secrets-store.js');
const { vendorKeySweepBlockedByFreshKey } = await import(
  './vendor-key-migration.runtime.js'
);

const keyFile = assertInsideSandbox(path.join(sandboxHome, '.nassaj-provider-secrets.key'));
const memberKeys = assertInsideSandbox(path.join(sandboxHome, '.nassaj-users', '42', '.provider-secrets', 'keys.json'));

/** An older keys.json, as a store sealed under a previous key would be. */
function writeOldKeysFile(): void {
  fs.mkdirSync(path.dirname(memberKeys), { recursive: true });
  fs.writeFileSync(memberKeys, '{}');
  const past = new Date(Date.now() - 60_000);
  fs.utimesSync(memberKeys, past, past);
}

beforeEach(() => {
  fs.rmSync(keyFile, { force: true });
  fs.rmSync(path.join(sandboxHome, '.nassaj-users'), { recursive: true, force: true });
  store._resetProviderSecretsServerKeyCache();
});
after(() => removeSandbox());

test('a key generated now over an older keys.json blocks the sweep', () => {
  writeOldKeysFile();
  assert.equal(store.isServerKeyFreshOverExistingStore(), true);
  assert.equal(fs.existsSync(keyFile), true, 'the key file was generated by this process');
  assert.equal(vendorKeySweepBlockedByFreshKey(), true);
});

test('a key generated on a fresh install (no stored keys) does not block the sweep', () => {
  assert.equal(store.isServerKeyFreshOverExistingStore(), false);
  assert.equal(vendorKeySweepBlockedByFreshKey(), false);
});

test('a key read from an existing file does not block the sweep', () => {
  store.isServerKeyFreshOverExistingStore();
  store._resetProviderSecretsServerKeyCache();
  writeOldKeysFile();
  assert.equal(store.isServerKeyFreshOverExistingStore(), false);
  assert.equal(vendorKeySweepBlockedByFreshKey(), false);
});

test('an unreadable key blocks the sweep', () => {
  writeOldKeysFile();
  process.env.NASSAJ_PROVIDER_SECRETS_KEY = 'not-a-valid-key';
  try {
    assert.equal(vendorKeySweepBlockedByFreshKey(), true);
  } finally {
    delete process.env.NASSAJ_PROVIDER_SECRETS_KEY;
  }
});
